	if value, ok := iuo.mutation.Address(); ok {
		_spec.SetField(instance.FieldAddress, field.TypeString, value)
	}
	if value, ok := iuo.mutation.Port(); ok {
		_spec.SetField(instance.FieldPort, field.TypeInt, value)
	}
	if value, ok := iuo.mutation.AddedPort(); ok {
		_spec.AddField(instance.FieldPort, field.TypeInt, value)
	}
